/// <summary>
/// MET_131601_PaymentRemitReportEmailSubjectChange developed by yadavpa on 10/04/2024
/// Email subject run time update
/// </summary>
[ExtensionOf(classStr(SRSPrintDestinationSettings))]
final class SRSPrintDestinationSettings_Metcash_Extension
{
    internal    str     reportTitle;
    //public      str     emailBody;
    internal    RecId   voucherRecId;
    internal    Name    metFileName;

}

Method.Source:
    [DataMemberAttribute]
    public RecId voucherRecId(RecId _voucherRecId = voucherRecId)
    {
        voucherRecId = _voucherRecId;

        return voucherRecId;
    }

    //Type of report
    [DataMemberAttribute]
    public str reportTitle(str _reportTitle = reportTitle) //To get Report Title from Print destinations form
    {
        reportTitle = _reportTitle;

        return reportTitle;
    }

    /// <summary>
    /// Email subject run time update
    /// </summary>
    /// <param name = "_emailContract">emailContract</param>
    /// <returns>emailContract</returns>
    public SrsReportEMailDataContract parmEMailContract(SrsReportEMailDataContract _emailContract)
    {
        SrsReportEmailDataContract  contract;
        ledgerJournalTrans          ledgerJournalTrans;

        contract = next parmEMailContract(_emailContract);
        
        if (reportTitle == "@MET:PaymentAdvice")
        {
            emailSubject =     contract.parmSubject();

            select firstonly ledgerJournalTrans where ledgerJournalTrans.RecId == voucherRecId; //RecId is used to get Related Report placeholder values

            emailSubject =  strReplace(emailSubject,"@MET:VendorAccountPlaceHolder",ledgerJournalTrans.accountDisplay());
            contract.parmSubject(emailSubject);
        }

        return contract;

    }

    /// <summary>
    /// CB713 PO confirmation - Task 91582
    /// To get Report file Name from Print destinations form
    /// </summary>
    /// <param name = "_fileName">SRSPrintDestinationSettings_Metcash_Extension</param>
    /// <returns>Name</returns>
    [DataMemberAttribute]
    public Name metFileName(Name _fileName = metFileName) 
    {
        metFileName = _fileName;

        return metFileName;
    }
